-- Customer analytics queries
-- Designed for PostgreSQL / MySQL 8+ / SQLite with minor syntax adjustments.
-- Main table: customer_rfm (generated by src/features.py and src/ingest.py)

-- 1. Top customers by historical revenue
SELECT CustomerName, monetary AS revenue, profit, frequency, recency
FROM customer_rfm
ORDER BY monetary DESC
LIMIT 20;

-- 2. High-value customers with above-average recency
-- These are candidates for retention review, not guaranteed churners.
SELECT CustomerName, recency, frequency, monetary, profit
FROM customer_rfm
WHERE monetary > (SELECT AVG(monetary) FROM customer_rfm)
  AND recency > (SELECT AVG(recency) FROM customer_rfm)
ORDER BY monetary DESC;

-- 3. Revenue concentration / cumulative share
WITH ranked AS (
    SELECT
        CustomerName,
        monetary,
        SUM(monetary) OVER (ORDER BY monetary DESC ROWS UNBOUNDED PRECEDING) AS cumulative_revenue,
        SUM(monetary) OVER () AS total_revenue
    FROM customer_rfm
)
SELECT
    CustomerName,
    monetary,
    ROUND(100.0 * cumulative_revenue / NULLIF(total_revenue, 0), 2) AS cumulative_revenue_pct
FROM ranked
ORDER BY monetary DESC;

-- 4. Customers by purchase frequency
SELECT
    frequency,
    COUNT(*) AS customers,
    ROUND(AVG(monetary), 2) AS avg_revenue,
    ROUND(AVG(profit), 2) AS avg_profit
FROM customer_rfm
GROUP BY frequency
ORDER BY frequency;

-- 5. Customers with strong frequency but lower-than-average monetary value
SELECT CustomerName, frequency, monetary, avg_order_value
FROM customer_rfm
WHERE frequency > (SELECT AVG(frequency) FROM customer_rfm)
  AND monetary < (SELECT AVG(monetary) FROM customer_rfm)
ORDER BY frequency DESC, monetary ASC;

-- 6. Profitability check
SELECT
    CustomerName,
    monetary AS revenue,
    profit,
    profit_margin_pct
FROM customer_rfm
WHERE monetary > 0
ORDER BY profit_margin_pct DESC;

-- 7. Simple customer ranking using a window function
SELECT
    CustomerName,
    monetary,
    RANK() OVER (ORDER BY monetary DESC) AS revenue_rank
FROM customer_rfm;
